// one pack person of an archetype, picked by population weight
function packPick(arch,x){const a=PACKBY[arch];if(!a||!a.length)return null;const r=x*a.tot;let lo=0,hi=a.length-1;while(lo<hi){const m=(lo+hi)>>1;if(a.cum[m]<r)lo=m+1;else hi=m}return a[lo]}
